const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='moonwish-v1';
let state={name:'',created:new Date().toISOString(),claim:null,wishes:[],visits:0};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved.name==='string'&&Array.isArray(saved.wishes))state={...state,...saved}}catch{}
try{if(!sessionStorage.getItem('moonwish-visit')){state.visits++;sessionStorage.setItem('moonwish-visit','1')}}catch{state.visits++}let storageWarning=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{if(!storageWarning){toast('Trình duyệt không cho phép lưu. Kết quả chỉ giữ trong lần mở này.');storageWarning=true}}}
const samples=[
{name:'Lan',content:'Mong những ngày sắp tới, bạn luôn gặp được những người tốt, những cơ hội tốt và đủ dũng cảm để theo đuổi điều mình thật sự muốn.'},
{name:'Minh',content:'Dù hôm nay có bận rộn đến đâu, mong bạn vẫn tìm được một khoảng bình yên để ngắm trăng và mỉm cười.'},
{name:'Huy',content:'Đừng quên rằng bạn đang làm rất tốt rồi. Cứ chậm rãi bước đi, những điều tốt đẹp đang đợi bạn ở phía trước.'},
{name:'Trang',content:'Mong bạn có một mùa Trung Thu thật ấm áp bên những người quan trọng. Ở đâu có yêu thương, ở đó là nhà.'},
{name:'An',content:'Chúc bạn luôn giữ được nụ cười hiện tại, và gặp nhiều điều tốt lành trong hành trình sắp tới!'},
{name:'Một người bạn',content:'Mong bạn luôn là phiên bản hạnh phúc nhất của chính mình. Trăng đêm nay thật đẹp, và bạn cũng vậy.'}
].map((x,i)=>({...x,id:'sample-'+i,sample:true,public:true}));
const defaults=[...samples.map(x=>x.content),'Mong những điều bạn đang chờ đợi đều tìm được đường đến với bạn, vào một ngày thật đẹp.','Chúc bạn một mùa trăng tròn đầy, đủ bình an để nghỉ ngơi và đủ niềm tin để bắt đầu những điều mới.'];
let toastTimer,expanded=false;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function displayName(w){return w.anonymous?'Một người bạn':w.name}
function render(){
$('#hero-name').textContent=state.name||'bạn';$('#sender-name').value=state.name;$('#profile-name').textContent=state.name||'Bạn';
$('#profile-date').textContent=new Date(state.created).toLocaleString('vi-VN',{dateStyle:'short',timeStyle:'short'});
$('#profile-wish').textContent=state.claim?state.claim.content:'Món quà vẫn đang chờ bạn.';
$('#profile-sent').textContent=state.wishes.length?state.wishes.map(w=>'“'+w.content+'”'+(w.public?'':' (Riêng tư)')).join('\n\n'):'Chưa có lời chúc nào.';
$('#visit-count').textContent=state.visits;$('#sent-count').textContent=state.wishes.length;$('#claim-count').textContent=state.claim?1:0;
$('#gift-cta').textContent=state.claim?'Xem lại lời chúc ☾':'Mở quà ngay ✧';
const visible=[...state.wishes.filter(w=>w.public).slice().reverse(),...samples];
$('#wish-list').replaceChildren();visible.slice(0,expanded?visible.length:4).forEach(w=>{const card=document.createElement('article');card.className='wish-card';const avatar=document.createElement('span');avatar.className='avatar';avatar.textContent=displayName(w).charAt(0);const body=document.createElement('div'),name=document.createElement('b'),p=document.createElement('p'),meta=document.createElement('small');name.textContent=displayName(w);p.textContent=w.content;meta.textContent=w.sample?'☾ Lời chúc minh họa':'☾ Bạn gửi · '+new Date(w.created).toLocaleString('vi-VN');body.append(name,p,meta);card.append(avatar,body);$('#wish-list').append(card)});
$('#more-wishes').hidden=visible.length<=4;$('#more-wishes').textContent=expanded?'Thu gọn ↑':'Xem thêm lời chúc ↓';
$('#sky-lanterns').replaceChildren();visible.slice(0,8).forEach((w,i)=>{const b=document.createElement('button');b.className='sky-lantern';b.style.left=[3,35,70,18,56,81,1,43][i]+'%';b.style.top=[85,0,67,227,188,260,270,310][i]+'px';b.style.animationDelay=(-i*.73)+'s';b.setAttribute('aria-label','Đọc lời chúc của '+displayName(w));const icon=document.createElement('img');icon.className='lantern-icon';icon.src='assets/sky-lantern.png';icon.alt='';const name=document.createElement('b');name.textContent=displayName(w);const tag=document.createElement('small');tag.textContent=w.sample?'Minh họa':'Bạn đã gửi';b.append(icon,name,tag);b.onclick=()=>showWish(w,false);$('#sky-lanterns').append(b)});
}
function start(name){name=String(name).trim();if(!name||name.length>40)throw new Error('Tên cần từ 1 đến 40 ký tự.');state.name=name;save();render();$('#welcome').close();return{name}}
$('#name-form').onsubmit=e=>{e.preventDefault();try{start($('#visitor-name').value)}catch(err){toast(err.message)}};
$('#welcome').addEventListener('cancel',e=>{if(!state.name)e.preventDefault()});$('#edit-name').onclick=()=>{$('#visitor-name').value=state.name;$('#welcome').showModal()};
function showWish(w,own){$('#dialog-title').textContent=own?state.name+' ơi, trăng gửi bạn…':'Một lời dưới ánh trăng';$('#dialog-kicker').textContent=w.sample?'LỜI CHÚC MINH HỌA':'MỘT CHÚT YÊU THƯƠNG GỬI ĐẾN BẠN';$('#received-content').textContent=w.content;$('#received-sender').textContent='— '+(own?'Một người bạn dưới ánh trăng ☾':displayName(w));$('#received-actions').hidden=!own;if(!$('#wish-dialog').open)$('#wish-dialog').showModal()}
let opening=false;
async function openGift(){if(document.body.dataset.page!=='gift'){location.href='gift.html';return{navigating:true}}if(!state.name){$('#welcome').showModal();return{needsName:true}}if(opening)return{opening:true};if(state.claim){showWish(state.claim,true);return{content:state.claim.content}}opening=true;$('.gift-object').classList.add('opening');$$('[data-action="gift"]').forEach(b=>b.disabled=true);await new Promise(r=>setTimeout(r,900));if(!state.claim){state.claim={content:defaults[Math.floor(Math.random()*defaults.length)],created:new Date().toISOString()};save()}$('.gift-object').classList.remove('opening');$$('[data-action="gift"]').forEach(b=>b.disabled=false);opening=false;render();showWish(state.claim,true);for(let i=0;i<22;i++){const s=document.createElement('span');s.className='spark';s.textContent='✦';s.style.setProperty('--dx',Math.cos(i)*180+'px');s.style.setProperty('--dy',Math.sin(i)*230+'px');$('#wish-dialog').append(s);setTimeout(()=>s.remove(),1600)}return{content:state.claim.content}}
$$('[data-action="gift"]').forEach(b=>b.onclick=openGift);
$('.close').onclick=()=>$('#wish-dialog').close();$('#leave-wish').onclick=()=>{$('#wish-dialog').close();location.href='write.html'};
$('#wish-content').oninput=e=>$('#char-count').textContent=e.target.value.length+'/300';
function sendWish(content,name,anonymous,isPublic){content=String(content).trim();name=String(name).trim();if(content.length<10||content.length>300)throw new Error('Lời chúc cần từ 10 đến 300 ký tự.');if(!name||name.length>40)throw new Error('Vui lòng nhập tên từ 1 đến 40 ký tự.');if(state.wishes.some(w=>w.content===content))throw new Error('Bạn đã gửi lời chúc này rồi.');if(state.wishes.length>=50)throw new Error('Bạn đã gửi đủ 50 lời chúc trong bản trải nghiệm.');const w={id:crypto.randomUUID(),name,content,anonymous:!!anonymous,public:!!isPublic,created:new Date().toISOString()};state.wishes.push(w);save();render();return{id:w.id,public:w.public}}
$('#wish-form').onsubmit=e=>{e.preventDefault();try{const result=sendWish($('#wish-content').value,$('#sender-name').value,$('#anonymous').checked,$('#public').checked);$('#wish-content').value='';$('#char-count').textContent='0/300';const letter=document.createElement('span');letter.className='flying-letter';letter.textContent='💌';document.body.append(letter);setTimeout(()=>{letter.remove();location.href=result.public?'sky.html':'profile.html'},2200);toast(result.public?'Lời chúc đã bay lên bầu trời của bạn ✨':'Lời chúc riêng tư đã được lưu trong Trang của bạn ♡')}catch(err){toast(err.message)}};
$('#more-wishes').onclick=()=>{expanded=!expanded;render()};
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Đã sao chép ♡')}catch{toast('Không thể sao chép tự động. Bạn có thể sao chép địa chỉ trên trình duyệt.')}}
async function share(text){if(navigator.share){try{await navigator.share({title:'Dưới Ánh Trăng · Trung Thu 2026',text,url:location.href.split('#')[0]})}catch(e){if(e.name!=='AbortError')await copy(text+'\n'+location.href.split('#')[0])}}else await copy(text+'\n'+location.href.split('#')[0])}
$('#copy-site').onclick=()=>copy(location.href.split('#')[0]);$('#share-site').onclick=()=>share('Có một món quà Trung Thu dành cho bạn ☾');$('#share-wish').onclick=()=>share(state.claim?.content||'');
$('#save-image').onclick=async()=>{if(!state.claim)return;await document.fonts.ready;const c=document.createElement('canvas');c.width=1080;c.height=1350;const ctx=c.getContext('2d'),gradient=ctx.createLinearGradient(0,0,1080,1350);gradient.addColorStop(0,'#101c35');gradient.addColorStop(1,'#271c30');ctx.fillStyle=gradient;ctx.fillRect(0,0,1080,1350);ctx.strokeStyle='#a8834c';ctx.lineWidth=2;ctx.strokeRect(45,45,990,1260);ctx.fillStyle='#f3c678';ctx.beginPath();ctx.arc(540,210,74,0,Math.PI*2);ctx.fill();ctx.textAlign='center';ctx.font='30px "Be Vietnam Pro"';ctx.fillText('TRUNG THU 2026',540,360);ctx.font='55px Charm';ctx.fillText(state.name,540,460,900);ctx.fillStyle='#fff0d9';ctx.font='48px Charm';const words=state.claim.content.split(/\s+/),lines=[];let line='';for(const w of words){if(ctx.measureText(line+' '+w).width>820){lines.push(line);line=w}else line+=(line?' ':'')+w}if(line)lines.push(line);lines.forEach((l,i)=>ctx.fillText(l,540,590+i*75));ctx.font='30px Charm';ctx.fillText('— Một người bạn dưới ánh trăng',540,1160);ctx.font='21px "Be Vietnam Pro"';ctx.fillStyle='#d4b782';ctx.fillText('DƯỚI ÁNH TRĂNG · NHẬN VÀ TRAO YÊU THƯƠNG',540,1230);c.toBlob(blob=>{if(!blob){toast('Chưa thể tạo ảnh. Vui lòng thử lại.');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='loi-chuc-trung-thu.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Đã tạo ảnh lời chúc để lưu ♡')},'image/png')};
let audioCtx=null,musicTimer=null,musicOn=false,notes=[261.63,329.63,392,523.25,440,392,329.63,293.66,261.63,392,440,523.25,659.25,523.25,392,329.63],noteIndex=0;
async function toggleMusic(){try{if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();if(musicOn){clearInterval(musicTimer);await audioCtx.suspend();musicOn=false}else{await audioCtx.resume();musicOn=true;const play=()=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=notes[noteIndex++%notes.length];g.gain.setValueAtTime(0,audioCtx.currentTime);g.gain.linearRampToValueAtTime(.085,audioCtx.currentTime+.06);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+1.9);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+2)};play();musicTimer=setInterval(play,750)}$('#music').textContent=musicOn?'Ⅱ':'♫';$('#music').setAttribute('aria-label',musicOn?'Tắt nhạc':'Bật nhạc');$('#music').setAttribute('aria-pressed',String(musicOn));$('#music-label').textContent=musicOn?'Đang phát · Chạm để tắt':'Chạm để lắng nghe'}catch{toast('Thiết bị chưa hỗ trợ âm thanh này.')}}
$('#music').onclick=toggleMusic;$('#music-card').onclick=toggleMusic;
for(let i=0;i<10;i++){const l=document.createElement('img');l.src='assets/sky-lantern.png';l.alt='';l.className='floating-lantern';l.style.cssText=`--x:${i*11}%;--size:${18+i%3*9}px;--duration:${25+i*2}s;--delay:${-i*6}s`;$('#atmosphere').append(l)}
for(let i=0;i<42;i++){const s=document.createElement('span');s.className='star';s.style.cssText=`--x:${(i*29.7)%100}%;--y:${(i*13.3)%100}%;--duration:${2+i%5}s;--delay:${-i}s`;$('#atmosphere').append(s)}
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});$$('.reveal').forEach(e=>observer.observe(e));
const sectionObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){$$('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===(e.target.id==='home'?'index.html':e.target.id+'.html')))}}),{rootMargin:'-20% 0px -55% 0px'});['home','wishes','sky','profile'].forEach(id=>sectionObserver.observe($('#'+id)));
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('paused-motion',document.hidden));
render();save();if(!state.name)$('#welcome').showModal();
if(document.modelContext?.registerTool){try{const result=document.modelContext.registerTool({name:'read_moonwish_state',description:'Read the current visitor name, received wish, and number of locally saved wishes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({name:state.name,receivedWish:state.claim?.content||null,sentCount:state.wishes.length,storage:'local-device-demo'})});Promise.resolve(result).catch(()=>{})}catch{}}

$('#show-qr').onclick=()=>$('#qr-dialog').showModal();$('#close-qr').onclick=()=>$('#qr-dialog').close();

$$('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===(document.body.dataset.page==='home'?'index.html':document.body.dataset.page+'.html')));
